style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://www.roblox.com/asset-thumbnail/image?assetId=1234567890") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important;
  }

  .navbar, .footer, .container-header, .game-home-page, .content, .container-main {
    background-color: rgba(0, 0, 0, 0.7) !important;
    border: none !important;
  }

  a, .text-link, .text-name, .text-robux {
    color: #ff4d4d !important;
  }

  .btn-primary, .btn-secondary, .btn-control-md {
    background-color: #ff4d4d !important;
    border-color: #ff4d4d !important;
    color: #fff !important;
  }

  .btn-primary:hover, .btn-secondary:hover {
    background-color: #ff1a1a !important;
    border-color: #ff1a1a !important;
  }

  .game-card-container, .game-card-thumb {
    border: 1px solid #ff4d4d !important;
    background-color: rgba(0, 0, 0, 0.5) !important;
  }

  .text-label, .section-content {
    color: #f0f0f0 !important;
  }
}
